      { "Section": "Environmental Risks", "Description": "..." },

      { "Section": "Potential Impacts", "Description": "..." },

      { "Section": "Recommendations", "Description": "..." },

      { "Section": "Uncertainties", "Description": "..." }

    ],

    "summary": {

      "Summary": "string"

    },

