      {

        "Hazard": "string",

        "Description": "string"

      }

    ],

    "ppe_observations": [

      {

        "PPE Element": "string",

        "Observed Compliance": "string",

        "Notes": "string"

      }

    ],

    "equipment_and_tools": [

      {

        "Equipment or Tool": "string",

        "Condition": "string",

        "Notes": "string"

      }

    ],

    "environmental_risks": [

      {

        "Risk": "string",

        "Description": "string"

      }

    ],

    "potential_impacts": [

