      "location": "string", // Lieu représenté (ex. "Rue urbaine", "Forêt")

      "time_of_day": "string", // Moment de la journée (ex. "Jour", "Nuit", "Crépuscule")

      "weather": "string" // Conditions météorologiques (ex. "Ensoleillé", "Pluvieux")

    },

    "elements_in_frame": {

      "primary_element": "string", // Focus principal (ex. "Personnage", "Objet")

      "secondary_elements": ["string"], // Autres éléments (ex. ["Arbre", "Bâtiment"])

      "position_in_frame": "string" // Position de l'élément principal (ex. "Centre", "Tiers gauche")

    },

    "mood": "string", // Ambiance véhiculée (ex. "Tendu", "Serein")

    "symbolism": "string" // Éléments symboliques (ex. "Miroir brisé pour la perte")

  },

  "contextual_information": {

