    "character_emotion": "string", // Émotion des personnages, si présents (ex. "Craintif", "Joyeux")

    "cultural_context": "string" // Contexte culturel ou historique (ex. "Décor d'après-guerre")

  },

  "analysis_notes": {

    "photographer": "string", // Nom du photographe ou directeur photo (ex. "Annie Leibovitz")

    "artistic_intent": "string", // Intention artistique (ex. "Souligner l'isolement")

    "technical_notes": "string" // Notes techniques supplémentaires

  }

}

